        public static Path Create(string pathData, double size = 14)
        {
            var path = new Path
            {
                Data = Geometry.Parse(pathData),
                Stretch = Stretch.Uniform,
                Width = size,
                Height = size,
                VerticalAlignment = VerticalAlignment.Center,
            };
            path.SetBinding(Shape.FillProperty, new Binding("Foreground")
            {
                RelativeSource = new RelativeSource(RelativeSourceMode.FindAncestor, typeof(Control), 1),
            });
            return path;
        }

        public static StackPanel Content(string pathData, string text, double iconSize = 14)
        {
            var sp = new StackPanel
            {
                Orientation = Orientation.Horizontal,
                VerticalAlignment = VerticalAlignment.Center,
            };
            var icon = Create(pathData, iconSize);
            icon.Margin = new Thickness(0, 0, 5, 0);
            sp.Children.Add(icon);
            sp.Children.Add(new TextBlock { Text = text, VerticalAlignment = VerticalAlignment.Center });
            return sp;
        }
    }
